CREATE TYPE "FamilyGroupStatus" AS ENUM ('ACTIVE', 'DISSOLVED');
CREATE TYPE "FamilyMemberRole" AS ENUM ('OWNER', 'MEMBER');
CREATE TYPE "FamilyMembershipStatus" AS ENUM ('ACTIVE', 'LEFT', 'REMOVED');
CREATE TYPE "FamilyInviteStatus" AS ENUM ('PENDING', 'ACCEPTED', 'DECLINED', 'CANCELLED', 'EXPIRED');
CREATE TYPE "NotificationType" AS ENUM ('FAMILY_INVITE_RECEIVED', 'INVITE_ACCEPTED', 'INVITE_DECLINED', 'MEMBER_REMOVED', 'GROUP_DISSOLVED');
CREATE TABLE "family_groups" ("id" SERIAL PRIMARY KEY, "name" TEXT NOT NULL, "status" "FamilyGroupStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3));
CREATE TABLE "family_memberships" ("id" SERIAL PRIMARY KEY, "familyGroupId" INTEGER NOT NULL, "userId" INTEGER NOT NULL, "role" "FamilyMemberRole" NOT NULL, "status" "FamilyMembershipStatus" NOT NULL DEFAULT 'ACTIVE', "joinedAt" TIMESTAMP(3) NOT NULL, "leftAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "family_memberships_familyGroupId_userId_key" UNIQUE ("familyGroupId", "userId"), CONSTRAINT "family_memberships_familyGroupId_fkey" FOREIGN KEY ("familyGroupId") REFERENCES "family_groups"("id") ON DELETE CASCADE, CONSTRAINT "family_memberships_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE TABLE "family_invites" ("id" SERIAL PRIMARY KEY, "familyGroupId" INTEGER NOT NULL, "inviterId" INTEGER NOT NULL, "inviteeId" INTEGER NOT NULL, "inviteeEmail" TEXT NOT NULL, "status" "FamilyInviteStatus" NOT NULL DEFAULT 'PENDING', "respondedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "family_invites_familyGroupId_fkey" FOREIGN KEY ("familyGroupId") REFERENCES "family_groups"("id") ON DELETE CASCADE, CONSTRAINT "family_invites_inviterId_fkey" FOREIGN KEY ("inviterId") REFERENCES "users"("id") ON DELETE CASCADE, CONSTRAINT "family_invites_inviteeId_fkey" FOREIGN KEY ("inviteeId") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE TABLE "notifications" ("id" SERIAL PRIMARY KEY, "userId" INTEGER NOT NULL, "type" "NotificationType" NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "payload" JSONB, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "notifications_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE INDEX "family_memberships_userId_status_idx" ON "family_memberships"("userId", "status");
CREATE INDEX "family_invites_inviteeId_status_idx" ON "family_invites"("inviteeId", "status");
CREATE INDEX "family_invites_familyGroupId_status_idx" ON "family_invites"("familyGroupId", "status");
CREATE INDEX "notifications_userId_readAt_createdAt_idx" ON "notifications"("userId", "readAt", "createdAt");
